/* Potion Shop service worker (generated by tools/pwa/apply_pwa.py: do not edit
 * the copy in the build; edit pwa/sw.template.js).
 * - Precaches every file of this build so the game starts offline.
 * - Each build has its own cache (version = hash of all files). A new version
 *   installs in the background and waits; the page offers "Restart" and then
 *   sends SKIP_WAITING. Old caches are deleted when the new version activates.
 * - Only same-origin GET requests are served from the cache. Ads and other
 *   third-party requests always go to the network and are never cached.
 * - Save data lives in localStorage, which the service worker never touches.
 */
'use strict';
const VERSION = '__VERSION__';
const CACHE = 'potion-shop-' + VERSION;
const PRECACHE = __PRECACHE__;

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE).then((cache) => cache.addAll(PRECACHE.map((p) => new Request(p, { cache: 'reload' }))))
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith('potion-shop-') && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') self.skipWaiting();
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return; // ads, analytics: network only
  event.respondWith(
    caches.open(CACHE).then((cache) =>
      cache.match(req, { ignoreSearch: true }).then((hit) => {
        if (hit) return hit;
        // Navigations (the start page) fall back to the cached index.html offline.
        return fetch(req).catch(() =>
          req.mode === 'navigate' ? cache.match('./index.html') : Response.error()
        );
      })
    )
  );
});
